import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.DFV5UN9c.js";const m=JSON.parse('{"title":"Runtime API 实验室","description":"用 VitePress 运行时 API 组合 Markdown、Vue、路由、资源路径和客户端交互。","frontmatter":{"title":"Runtime API 实验室","description":"用 VitePress 运行时 API 组合 Markdown、Vue、路由、资源路径和客户端交互。","layout":"runtime-lab","tags":["VitePress","Vue","Runtime API"]},"headers":[],"relativePath":"runtime-api.md","filePath":"runtime-api.md"}'),o={name:"runtime-api.md"};function i(n,t,l,c,s,u){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="api-能把站点扩展到什么程度" tabindex="-1">API 能把站点扩展到什么程度 <a class="header-anchor" href="#api-能把站点扩展到什么程度" aria-label="Permalink to &quot;API 能把站点扩展到什么程度&quot;">​</a></h1><p>VitePress 的运行时 API 不是大型应用框架的替代品，但它足够把一个普通博客升级成“知识工作台”。</p><p>它最适合承担这些能力：</p><table tabindex="0"><thead><tr><th>API</th><th>可以做的事情</th></tr></thead><tbody><tr><td><code>useData()</code></td><td>读取站点配置、主题配置、当前页面 frontmatter、标题、暗色模式</td></tr><tr><td><code>useRoute()</code></td><td>感知当前路径，用于页面状态、阅读轨迹、上下文面板</td></tr><tr><td><code>useRouter()</code></td><td>在 Vue 组件里做程序化跳转、向导流程、项目卡片导航</td></tr><tr><td><code>withBase()</code></td><td>处理 public 静态资源路径，避免部署到子路径后资源失效</td></tr><tr><td><code>&lt;Content /&gt;</code></td><td>自定义布局中继续渲染 Markdown 正文</td></tr><tr><td><code>&lt;ClientOnly /&gt;</code></td><td>包住 canvas、WebGL、localStorage、编辑器等浏览器专用组件</td></tr><tr><td><code>$frontmatter</code></td><td>在 Markdown 中快速读取页面元数据</td></tr></tbody></table><h2 id="适合你这个站点的方向" tabindex="-1">适合你这个站点的方向 <a class="header-anchor" href="#适合你这个站点的方向" aria-label="Permalink to &quot;适合你这个站点的方向&quot;">​</a></h2><ol><li>全屏 Vue 工作台：已经用于 <code>/workspace</code>。</li><li>交互式简历和项目详情：已经用于 <code>/about/</code>。</li><li>Runtime API 实验室：当前页面展示 Markdown 与 Vue 面板并排。</li><li>后续可以做文章知识图谱、项目关系图、标签分析、阅读路线推荐。</li></ol><h2 id="markdown-仍然有价值" tabindex="-1">Markdown 仍然有价值 <a class="header-anchor" href="#markdown-仍然有价值" aria-label="Permalink to &quot;Markdown 仍然有价值&quot;">​</a></h2><p>即使做交互页面，也不必完全抛弃 Markdown。比较好的组合是：</p><ol><li>Markdown 写说明、背景、结论。</li><li>Vue 负责交互、筛选、可视化和跳转。</li><li>自定义 Layout 决定页面是不是文档风格、实验室风格或全屏应用风格。</li></ol><p>这个页面就是这种模式：左侧是 Markdown 内容，右侧是运行时 API 面板和客户端 canvas。</p>',10)])])}const h=e(o,[["render",i]]);export{m as __pageData,h as default};
